CREATE OR REPLACE FUNCTION private.kp_apply_reply(p_id text, p_token uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r private.kp_replies;c private.kp_contacts;cfg private.kp_companies;newstep int;msg text;
begin
 select co.* into c from private.kp_contacts co join private.kp_replies rp on rp.contact_id=co.id where rp.id=p_id for update of co;
 select * into r from private.kp_replies where id=p_id for update;
 if not found or r.token is distinct from p_token or p_token is null then raise exception 'Invalid reply token';end if;
 if r.status='done' then return jsonb_build_object('duplicate',true);end if;
 if r.status<>'processing' or c.generation<>r.generation or c.status<>'answered' then
  update private.kp_replies set status='stale' where id=r.id;return jsonb_build_object('stale',true);
 end if;
 if exists(select 1 from public.lead where id=c.legacy_lead_id and (atendimento_humano or wa_conversation_assigned_to is not null)) then
  update private.kp_contacts set status='human' where id=c.id;update private.kp_replies set status='done',decision='human' where id=r.id;return jsonb_build_object('human',true);
 end if;
 select * into cfg from private.kp_companies where id_empresa=c.id_empresa;
 if not cfg.enabled then raise exception 'Campaign paused';end if;
 if p_action='identity_confirmed' and c.phase='identity' and not exists(select 1 from private.kp_jobs where contact_id=c.id and step=4) then
  newstep:=4;msg:='Perfeito '||c.name||E'!\n\nTrabalho com incorporadoras há 8 anos e criei uma IA para atendimento de leads e agendamento de visitas que tem aumentado o resultado de vendas dos nossos clientes.\n\nPosso te mostrar como funciona?';
 elsif p_action='automatic' then
  -- One presentation per contact; the unique step also prevents bot loops.
  if not exists(select 1 from private.kp_jobs where contact_id=c.id and step=4) then
   newstep:=4;
   msg:='Aqui é a Ana, da Katsuki. Trabalhamos com IA para atendimento de leads e agendamento de visitas em incorporadoras. Quando puder, me conta se faz sentido conhecer a solução.';
  end if;
 elsif p_action in ('interested','response_received') then
  -- Persist the decision before the helper validates it.
  update private.kp_replies set status='done',decision=p_action where id=r.id;
  if exists(select 1 from private.kp_jobs where contact_id=c.id and step=4 and status='accepted') then
   perform private.kp_handoff_presented(c.id,r.id);
  else
   msg:=E'Obrigada pelo retorno! Aqui é a Ana, da Katsuki.\n\nTrabalho com incorporadoras há 8 anos e criei uma IA para atendimento de leads e agendamento de visitas que tem aumentado o resultado de vendas dos nossos clientes.\n\nPosso te mostrar como funciona?';
   insert into private.kp_jobs(contact_id,step,due_at,generation,body,reply_id)
   values(c.id,4,clock_timestamp(),c.generation,msg,r.id)
   on conflict(contact_id,step) where step<=5 do update
   set status='pending',due_at=excluded.due_at,generation=excluded.generation,body=excluded.body,reply_id=excluded.reply_id,error=null
   where kp_jobs.status in ('pending','cancelled') and kp_jobs.message_id is null and kp_jobs.reserved_at is null;
   -- Sending/uncertain outcomes are never retried here.
  end if;
 elsif p_action='declined' then
  update private.kp_contacts set status='declined' where id=c.id;
  newstep:=5;msg:='Tudo bem'||case when nullif(btrim(c.name),'') is not null then ', '||btrim(c.name) else '' end||'! Agradeço pelo retorno e pela atenção. Tenha um ótimo dia!';
 elsif p_action in ('opt_out','wrong_person') then
  update private.kp_contacts set status='stopped' where id=c.id;
 else
  update private.kp_contacts set status='review' where id=c.id;
 end if;
 if newstep is not null then
  insert into private.kp_jobs(contact_id,step,due_at,generation,body) values(c.id,newstep,clock_timestamp(),c.generation,msg) on conflict do nothing;
 end if;
 update private.kp_replies set status='done',decision=p_action where id=r.id;
 return jsonb_build_object('action',p_action,'contact_id',c.id);
end $function$

CREATE OR REPLACE FUNCTION private.kp_capture_reply()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c private.kp_contacts;received timestamptz;matches uuid[];body text;
begin
 if new.direction<>'inbound' or new.message_id is null then return new;end if;
 select array_agg(co.id) into matches from private.kp_contacts co join private.kp_companies cf on cf.id_empresa=co.id_empresa
  where cf.enabled and cf.phone_number_id=new.phone_number_id and (new.tenant_id is null or co.id_empresa=new.tenant_id)
    and (co.phone=new.from_wa_id or (new.from_wa_id ~ '^55[0-9]{10}$' and co.phone=overlay(new.from_wa_id placing '9' from 5 for 0)));
 if cardinality(matches) is distinct from 1 then return new;end if;
 select * into c from private.kp_contacts where id=matches[1] for update;
 if not found or exists(select 1 from private.kp_replies where id=new.message_id) then return new;end if;

 if c.crm_lead_id is null then
  if c.status<>'active' then return new;end if;
  update private.kp_contacts set whatsapp_check='confirmado',whatsapp_check_at=clock_timestamp() where id=c.id;
  perform private.kp_materialize_contact(c.id);
  select * into c from private.kp_contacts where id=c.id;
 end if;
 received:=coalesce(new.timestamp_meta,new.created_at,clock_timestamp());
 if c.last_reply_at is not null and received<c.last_reply_at then return new;end if;
 update private.kp_contacts set generation=generation+1,last_reply_id=new.message_id,last_reply_at=received,
  status=case when status in ('interested','declined','stopped','human') then status else 'answered' end
  where id=c.id returning * into c;
 update private.kp_jobs set status='cancelled' where contact_id=c.id and status='pending';
 body:=coalesce(new.text_body,new.raw#>>'{message,text,body}','');
 insert into private.kp_replies(id,contact_id,generation,body,status)
 values(new.message_id,c.id,c.generation,body,case when c.status='answered' then 'pending' else 'done' end);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.kp_claim(p_kind text, p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare cfg private.kp_companies;c private.kp_contacts;j private.kp_jobs;t private.kp_templates;
 parts jsonb;params jsonb;payload jsonb;v text;v_body text;greeting text;count_today int;
begin
 if p_kind not in ('opening','followup','reply') then raise exception 'Invalid worker kind';end if;
 if not private.kp_business_time(p_now) then return;end if;
 for cfg in select * from private.kp_companies where enabled order by operation for update skip locked loop
  if not exists(select 1 from public.credentials cr where cr.id_empresa=cfg.id_empresa
    and cr.whatsapp_business_id=cfg.phone_number_id and nullif(cr.whatsapp_access_token,'') is not null) then continue;end if;
  if p_kind <> 'reply' and (select count(*) from private.kp_templates where id_empresa=cfg.id_empresa and approved) <> 4 then continue;end if;
  if p_kind='opening' then
   select count(*) into count_today from private.kp_jobs x join private.kp_contacts co on co.id=x.contact_id
    where co.id_empresa=cfg.id_empresa and x.step=0 and x.booked_day=(p_now at time zone 'America/Sao_Paulo')::date;
   if count_today>=cfg.daily_limit or cfg.last_opening_reserved_at + interval '650 minutes'/cfg.daily_limit > p_now then continue;end if;
  end if;
  for j in select x.* from private.kp_jobs x join private.kp_contacts co on co.id=x.contact_id
   where co.id_empresa=cfg.id_empresa and x.status='pending' and x.due_at<=p_now and (p_kind<>'opening' or co.whatsapp_check='confirmado')
    and ((p_kind='opening' and x.step=0) or (p_kind='followup' and x.step between 1 and 3) or (p_kind='reply' and x.step in(4,5,6)))
   order by x.due_at,x.id for update of x skip locked limit 1 loop
   select * into c from private.kp_contacts where id=j.contact_id for update;
   if exists(select 1 from public.lead where id=c.legacy_lead_id and (atendimento_humano or wa_conversation_assigned_to is not null)) then
    update private.kp_contacts set status='human' where id=c.id;
    update private.kp_jobs set status='cancelled' where contact_id=c.id and status='pending';continue;
   end if;
   if c.generation<>j.generation or (j.step<=3 and c.status<>'active') or (j.step in(4,6) and c.status<>'answered') or (j.step=5 and c.status<>'declined') then
    update private.kp_jobs set status='cancelled' where id=j.id;continue;
   end if;
   if j.step between 1 and 3 and (c.first_sent_at is null or c.last_sent_at+interval '1 hour'>p_now) then continue;end if;
   if exists(select 1 from private.kp_jobs x where x.contact_id=c.id and x.step<j.step and x.step<=3 and x.status not in ('accepted','cancelled')) then continue;end if;
   if j.step<=3 then
    if not public.wa_marketing_send_guard(cfg.phone_number_id,c.phone,null::bigint) then
     update private.kp_contacts set status='stopped' where id=c.id;
     update private.kp_jobs set status='cancelled' where contact_id=c.id and status='pending';continue;
    end if;
    select * into t from private.kp_templates where id_empresa=cfg.id_empresa and step=j.step and approved;
    if not found then continue;end if;
    parts:='[]'::jsonb;params:='[]'::jsonb;
    greeting:=case when (p_now at time zone 'America/Sao_Paulo')::time < time '12:00' then 'Bom dia' else 'Boa tarde' end;
    v_body:=replace(replace(t.body,'[Nome]',c.name),'[Saudacao]',greeting);
    if t.media_type is not null then
     parts:=parts||jsonb_build_array(jsonb_build_object('type','header','parameters',jsonb_build_array(jsonb_build_object('type',t.media_type,t.media_type,case when t.media_url is null then jsonb_build_object('id',t.media_id) else jsonb_build_object('link',t.media_url) end))));
    end if;
    foreach v in array t.variables loop
     if v not in ('name','greeting') then raise exception 'Unknown template variable';end if;
     params:=params||jsonb_build_array(jsonb_build_object('type','text','text',case when v='name' then c.name else greeting end));
    end loop;
    if jsonb_array_length(params)>0 then parts:=parts||jsonb_build_array(jsonb_build_object('type','body','parameters',params));end if;
    payload:=jsonb_build_object('messaging_product','whatsapp','to',c.phone,'type','template','template',jsonb_build_object('name',t.name,'language',jsonb_build_object('code','pt_BR'),'components',parts));
   else
    -- Customer-service window is tied to the actual inbound message, not opening.
    if c.last_reply_at is null or c.last_reply_at+interval '24 hours'<=p_now then
     update private.kp_jobs set status='review',error='customer_window_closed' where id=j.id;continue;
    end if;
    v_body:=j.body;
    payload:=jsonb_build_object('messaging_product','whatsapp','to',c.phone,'type','text','text',jsonb_build_object('body',v_body));
   end if;
   if j.step=0 and c.crm_lead_id is null then
    perform private.kp_materialize_contact(c.id);
    select * into c from private.kp_contacts where id=c.id;
   end if;
   update private.kp_jobs set status='sending',token=gen_random_uuid(),reserved_at=p_now,
    booked_day=(p_now at time zone 'America/Sao_Paulo')::date,body=v_body where id=j.id returning * into j;
   if j.step=0 then update private.kp_companies set last_opening_reserved_at=p_now where id_empresa=cfg.id_empresa;end if;
   insert into public.wa_messages(phone_number_id,client_message_id,direction,to_wa_id,type,text_body,template_name,template_language,
    status_current,tenant_id,crm_entity_id,crm_entity_type,crm_provider,crm_sync_status,raw)
   values(cfg.phone_number_id,'kp:'||j.id,'outbound',c.phone,payload->>'type',v_body,case when j.step<=3 then t.name end,'pt_BR',
    'preparing',cfg.id_empresa,c.crm_lead_id::text,'lead','hub','pending',jsonb_build_object('source','katsuki_prospect','job_id',j.id,'step',j.step));
   return next jsonb_build_object('job_id',j.id,'token',j.token,'id_empresa',cfg.id_empresa,'phone_number_id',cfg.phone_number_id,'payload',payload);
  end loop;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION private.kp_complete(p_id uuid, p_token uuid, p_message_id text, p_error text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j private.kp_jobs;c private.kp_contacts;i int;offsets int[]:=array[2,23,50];
begin
 select co.* into c from private.kp_contacts co join private.kp_jobs x on x.contact_id=co.id where x.id=p_id for update of co;
 select * into j from private.kp_jobs where id=p_id for update;
 if not found or j.token is distinct from p_token or p_token is null then raise exception 'Invalid send receipt';end if;
 if j.status='accepted' and j.message_id=p_message_id then return jsonb_build_object('duplicate',true);end if;
 if j.status<>'sending' then raise exception 'Job not awaiting receipt';end if;
 if p_message_id is null or p_message_id not like 'wamid.%' or p_error is not null then
  update private.kp_jobs set status='review',error=coalesce(p_error,'unknown_transport_outcome') where id=j.id;
  update private.kp_contacts set status='review' where id=c.id and status='active';
  return jsonb_build_object('accepted',false,'review',true);
 end if;
 update private.kp_jobs set status='accepted',message_id=p_message_id,accepted_at=p_now where id=j.id;
 update public.wa_messages set message_id=p_message_id,sent_at=coalesce(sent_at,p_now),
  status_current=case when status_current in ('sent','delivered','read','failed') then status_current else 'accepted' end
  where client_message_id='kp:'||j.id and tenant_id=c.id_empresa;
 update private.kp_contacts set last_sent_at=p_now,last_outbound=j.body,
  phase=case when j.step>=1 then 'offer' else phase end,
  first_sent_at=case when j.step=0 then coalesce(first_sent_at,p_now) else first_sent_at end,
  status=case when j.step=3 and status='active' then 'complete' else status end where id=c.id;
 if j.step=0 and c.status='active' and c.generation=j.generation then
  for i in 1..3 loop
   insert into private.kp_jobs(contact_id,step,due_at,generation) values(c.id,i,p_now+offsets[i]*interval '1 hour',c.generation) on conflict do nothing;
  end loop;
 end if;
 if j.step=4 and j.reply_id is not null and c.generation=j.generation then
  perform private.kp_handoff_presented(c.id,j.reply_id);
 end if;
 return jsonb_build_object('accepted',true);
end $function$

CREATE OR REPLACE FUNCTION private.kp_handoff_presented(p_contact uuid, p_reply text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c private.kp_contacts;r private.kp_replies;cfg private.kp_companies;
begin
 select * into c from private.kp_contacts where id=p_contact for update;
 select * into r from private.kp_replies where id=p_reply and contact_id=c.id;
 if c.id_empresa not in (35,36) or c.status<>'answered' or r.id is null
 or r.generation<>c.generation or r.status<>'done' or r.decision not in ('response_received','interested')
 or c.last_reply_id is distinct from r.id then return false;end if;
 select * into cfg from private.kp_companies where id_empresa=c.id_empresa;
 if not cfg.enabled then return false;end if;
 perform 1 from public.lead where id=c.legacy_lead_id and id_empresa=c.id_empresa for update;
 if exists(select 1 from public.lead where id=c.legacy_lead_id and (atendimento_humano or wa_conversation_assigned_to is not null)) then return false;end if;
 if not exists(select 1 from private.kp_jobs where contact_id=c.id and step=4 and status='accepted') then return false;end if;
 update private.kp_contacts set status='human' where id=c.id;
 update public.lead set atendimento_humano=true,atendimento_humano_desde=clock_timestamp(),status='desativado' where id=c.legacy_lead_id and id_empresa=c.id_empresa;
 if cfg.interested_stage_id is not null then
  if not exists(select 1 from public.crm_stages where id=cfg.interested_stage_id and id_empresa=c.id_empresa and ativo) then raise exception 'Invalid handoff stage';end if;
  update public.crm_leads set crm_stage_id=cfg.interested_stage_id where id=c.crm_lead_id and id_empresa=c.id_empresa;
 end if;
 insert into private.kp_handoffs(contact_id,reply_id) values(c.id,r.id) on conflict(contact_id) do nothing;
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.kp_on_takeover()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.wa_conversation_assigned_to is null then return new;end if;
 update private.kp_contacts c set status='human',generation=generation+1
 where c.legacy_lead_id=new.id and c.id_empresa=new.id_empresa;
 update private.kp_jobs j set status='cancelled' from private.kp_contacts c
 where c.id=j.contact_id and c.legacy_lead_id=new.id and c.id_empresa=new.id_empresa and j.status='pending';
 update private.kp_handoffs h set status='assumed',seen_at=coalesce(seen_at,clock_timestamp())
 from private.kp_contacts c where c.id=h.contact_id and c.legacy_lead_id=new.id and c.id_empresa=new.id_empresa;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.kp_preflight(p_id uuid, p_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j private.kp_jobs;c private.kp_contacts;cfg private.kp_companies;
begin
 select co.* into c from private.kp_contacts co join private.kp_jobs x on x.contact_id=co.id where x.id=p_id for update of co;
 select * into j from private.kp_jobs where id=p_id and token=p_token and status='sending' for update;
 if not found then return false;end if;
 select * into cfg from private.kp_companies where id_empresa=c.id_empresa;
 if not cfg.enabled or not private.kp_business_time(clock_timestamp()) or c.generation<>j.generation
  or (j.step<=3 and c.status<>'active')
  or (j.step in(4,6) and c.status<>'answered')
  or exists(select 1 from public.lead where id=c.legacy_lead_id and (atendimento_humano or wa_conversation_assigned_to is not null))
  or (j.step<=3 and not public.wa_marketing_send_guard(cfg.phone_number_id,c.phone,null::bigint))
  or (j.step>=4 and c.last_reply_at+interval '24 hours'<=clock_timestamp()) then
  update private.kp_jobs set status='cancelled',error='preflight_state_changed' where id=j.id;
  return false;
 end if;
 return true;
end $function$
